    fn test_build_ignored_in_compare() -> Result<(), String> {
        let ord = cmp("1.0.0+build", "1.0.0")?;
        if ord != Ordering::Equal { return Err("build should be ignored in compare".to_string()); }
        Ok(())
    }

    #[test]
    fn test_bumps() -> Result<(), String> {
        let v = parse("1.2.3").map_err(|e| e)?;
        let m = bump_major(&v);
        if to_string(&m) != "2.0.0" { return Err("major bump failed".to_string()); }
