        if ident.is_empty() {
            return false;
        }
        if ident.chars().all(|c| c.is_ascii_digit()) {
            // numeric identifier: allow "0" or numbers without leading zeros
            if ident.len() > 1 && ident.as_bytes()[0] == b'0' {
                return false;
            }
        } else {
            // alphanumeric: must be ASCII alphanumeric or '-'
            if ident.chars().any(|c| !(c.is_ascii_alphanumeric() || c == '-')) {
