fn valid_build(build: &str) -> bool {
    // build identifiers: dot-separated, each [0-9A-Za-z-]+
    for ident in build.split('.') {
        if ident.is_empty() {
            return false;
        }
        if ident.chars().any(|c| !(c.is_ascii_alphanumeric() || c == '-')) {
