        return Err(format!("{} is not valid SemVer string", s));
    }
    if (major_s.len() > 1 && major_s.as_bytes()[0] == b'0')
        || (minor_s.len() > 1 && minor_s.as_bytes()[0] == b'0')
        || (patch_s.len() > 1 && patch_s.as_bytes()[0] == b'0') {
        return Err(format!("{} is not valid SemVer string", s));
    }

    let major = parse_u64_from_digits(major_s).ok_or_else(|| format!("{} is not valid SemVer string", s))?;
    let minor = parse_u64_from_digits(minor_s).ok_or_else(|| format!("{} is not valid SemVer string", s))?;
